import XCTest
import AppKit
@testable import MagnusVector

/// A golden native document generated by PressCheck's carton prototype exporter.
/// The drawing is explicitly unverified tooling, not a supplier's approved dieline.
final class ProductionInteroperabilityTests: XCTestCase {
    private func fixtureData() throws -> Data {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "PressCheck-Carton", withExtension: "mvector", subdirectory: "Fixtures"))
        return try Data(contentsOf: url)
    }
    private func fixture() throws -> VectorProject {
        try JSONDecoder().decode(VectorProject.self, from: fixtureData()).validated()
    }
    func testPressCheckNativeCartonKeepsGeometryIdentifiersLayersAndInheritedRoles() throws {
        let project = try fixture()
        XCTAssertEqual(project.version, 2)
        XCTAssertEqual(project.width, 226); XCTAssertEqual(project.height, 213.5)
        XCTAssertEqual(project.shapes.count, 25)
        XCTAssertEqual(project.rootNodes.map(\.kind), Array(repeating: .layer, count: 5))
        XCTAssertEqual(project.rootNodes.map { $0.children.count }, [1,12,1,7,4])
        XCTAssertEqual(project.rootNodes.flatMap(\.objectIDs), project.shapes.map(\.id))
        XCTAssertEqual(Set(project.shapes.map(\.id)).count, 25)
        let cut = try XCTUnwrap(project.shapes.first)
        let raw = try XCTUnwrap(JSONSerialization.jsonObject(with: fixtureData()) as? [String: Any])
        let inputShapes = try XCTUnwrap(raw["shapes"] as? [[String: Any]])
        XCTAssertEqual(project.shapes.map { $0.id.uuidString.lowercased() }, inputShapes.compactMap { $0["id"] as? String })
        XCTAssertEqual(cut.name, "Cut outline"); XCTAssertEqual(cut.kind, .path); XCTAssertTrue(cut.closed)
        XCTAssertNil(cut.fill); XCTAssertEqual(cut.strokeWidth, 0.25)
        XCTAssertEqual(cut.bounds, CGRect(x: 12, y: 12, width: 202, height: 167.5))
        let crease = project.shapes[1]
        XCTAssertEqual(crease.name, "Crease 1"); XCTAssertFalse(crease.closed)
        XCTAssertEqual(crease.anchors.map(\.point), [VectorPoint(24,45.75), VectorPoint(24,145.75)])
        let roles = project.shapes.map { project.hierarchyIndex.productionRoles[$0.id] }
        XCTAssertEqual(roles.filter { $0 == .cut }.count, 1)
        XCTAssertEqual(roles.filter { $0 == .crease }.count, 12)
        XCTAssertEqual(roles.filter { $0 == .glue }.count, 1)
        XCTAssertEqual(roles.filter { $0 == .legend }.count, 11)
        XCTAssertEqual(try JSONDecoder().decode(VectorProject.self, from: JSONEncoder().encode(project)).validated(), project)
    }
    func testProductionExportPreservesCartonMillimeterScaleAndLegalUnconfirmedJob() throws {
        let project = try fixture(), before = project
        let spec = try XCTUnwrap(project.production).validated()
        XCTAssertEqual(spec.workflow, .packaging)
        XCTAssertEqual(spec.trimWidthMM, 226); XCTAssertEqual(spec.trimHeightMM, 213.5)
        XCTAssertEqual(spec.bleedMM, 0); XCTAssertEqual(spec.safeMM, 0)
        XCTAssertEqual(spec.bleedIntent, .whiteBorder); XCTAssertEqual(spec.colorPolicy, .reviewRGB)
        XCTAssertEqual(spec.expectedRoles, [.cut,.crease,.glue]); XCTAssertFalse(spec.supplierConfirmed)
        XCTAssertTrue(try XCTUnwrap(spec.printerNotes).contains("not finished-carton trim"))
        let layout = try spec.layout(for: project)
        XCTAssertEqual(layout.scale, 72 / 25.4, accuracy: 1e-12)
        XCTAssertEqual(layout.x, 0, accuracy: 1e-10); XCTAssertEqual(layout.y, 0, accuracy: 1e-10)
        let cut = project.shapes[0]
        XCTAssertEqual(cut.bounds.width * layout.scale / ProductionSpec.pointsPerMM, 202, accuracy: 1e-10)
        XCTAssertEqual((cut.anchors[0].point.x * layout.scale + layout.x) / ProductionSpec.pointsPerMM, 24, accuracy: 1e-10)
        let xml = try XMLDocument(data: ProductionSVGExporter.data(project, spec: spec), options: [.nodeLoadExternalEntitiesNever])
        let root = try XCTUnwrap(xml.rootElement())
        XCTAssertEqual(root.attribute(forName: "width")?.stringValue, "226.0mm")
        XCTAssertEqual(root.attribute(forName: "height")?.stringValue, "213.5mm")
        let boxes = try XCTUnwrap(root.attribute(forName: "viewBox")?.stringValue).split(separator: " ").compactMap { Double($0) }
        XCTAssertEqual(boxes[2] / ProductionSpec.pointsPerMM, 226, accuracy: 1e-10)
        XCTAssertEqual(boxes[3] / ProductionSpec.pointsPerMM, 213.5, accuracy: 1e-10)
        let objectNodes = try xml.nodes(forXPath: "//*[starts-with(@id,'object_')]").compactMap { $0 as? XMLElement }
        XCTAssertEqual(objectNodes.map { $0.attribute(forName: "id")?.stringValue }, project.shapes.map { SVGExporter.objectID($0) })
        XCTAssertEqual(objectNodes[0].attribute(forName: "data-production-role")?.stringValue, "cut")
        XCTAssertEqual(objectNodes[0].attribute(forName: "d")?.stringValue, SVGExporter.pathData(cut))
        XCTAssertEqual(objectNodes[1].attribute(forName: "data-production-role")?.stringValue, "crease")
        XCTAssertEqual(try xml.nodes(forXPath: "//*[@data-magdobe-kind='layer']").count, 5)
        XCTAssertEqual(try xml.nodes(forXPath: "//*[local-name()='image' or local-name()='foreignObject' or local-name()='script']").count, 0)
        let metadata = try XCTUnwrap(xml.nodes(forXPath: "//*[@id='magdobe-production-job']").first?.stringValue)
        XCTAssertEqual(try JSONDecoder().decode(ProductionSpec.self, from: Data(metadata.utf8)).validated(), spec)
        let job = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(metadata.utf8)) as? [String: Any])
        XCTAssertEqual(job["schema_version"] as? Int, 1)
        XCTAssertEqual(job["supplier_confirmed"] as? Bool, false)
        XCTAssertEqual(job["expected_roles"] as? [String], ["cut","crease","glue"])
        XCTAssertNil(job["api_key"]); XCTAssertNil(job["pdfx_certified"])
        XCTAssertEqual(project, before)
    }
    func testGroupingImportedOperationsRetainsScaleAndChildRoleOverride() throws {
        var project = try fixture()
        let before = project.shapes
        let creaseLayerID = project.rootNodes[1].id
        let groupID = UUID()
        project.updateHierarchy { roots in
            VectorProject.editNode(creaseLayerID, in: &roots) { layer in
                layer.children = [VectorNode(id: groupID, kind: .group, name: "Editable fold lines", children: layer.children)]
            }
        }
        _ = try project.validated()
        XCTAssertEqual(project.shapes, before)
        XCTAssertEqual(project.hierarchyIndex.productionRoles[groupID], .crease)
        XCTAssertEqual(project.hierarchyIndex.productionRoles[project.shapes[1].id], .crease)
        let decoded = try JSONDecoder().decode(VectorProject.self, from: JSONEncoder().encode(project)).validated()
        XCTAssertEqual(decoded, project)
        let xml = try XMLDocument(data: ProductionSVGExporter.data(decoded, spec: XCTUnwrap(decoded.production)), options: [.nodeLoadExternalEntitiesNever])
        let groups = try xml.nodes(forXPath: "//*[@data-magdobe-kind='group']").compactMap { $0 as? XMLElement }
        XCTAssertEqual(groups.count, 1)
        XCTAssertEqual(groups[0].attribute(forName: "data-production-role")?.stringValue, "crease")
        XCTAssertEqual(groups[0].attribute(forName: "id")?.stringValue, "group_" + groupID.uuidString.lowercased())
        XCTAssertEqual(try groups[0].nodes(forXPath: "./*[starts-with(@id,'object_')]").count, 12)
    }
}
